-- F1-14: plan, allocation and terms hash in plpgsql (paramnet-domain principle 8).
-- These mirror packages/shared plan.ts, allocation.ts and terms-hash.ts and are checked against the same
-- vectors (supabase/tests/database/030_domain_vectors.test.sql, generated by `pnpm db:vectors`).
-- Errors are raised as SQLSTATE P0001 with the same codes the TypeScript result types use (inline
-- `raise`, so plpgsql_check can see every branch).

create schema if not exists private;

-- Helpers -------------------------------------------------------------------------------------------

-- Same range as Number.isSafeInteger, non-negative (isMinorAmount).
create function private.is_minor(p_value jsonb) returns boolean
language sql
stable
set search_path = ''
as $$
	select coalesce(
		jsonb_typeof(p_value) = 'number'
			and (p_value #>> '{}')::numeric = trunc((p_value #>> '{}')::numeric)
			and (p_value #>> '{}')::numeric between 0 and 9007199254740991,
		false
	);
$$;

-- "YYYY-MM-DD" that is a real calendar day, else null (isIsoDate).
create function private.try_date(p_value text) returns date
language plpgsql
stable
set search_path = ''
as $$
begin
	if p_value is null or p_value !~ '^\d{4}-\d{2}-\d{2}$' then
		return null;
	end if;
	return p_value::date;
exception when others then
	return null;
end;
$$;

-- Shared by generate_plan and validate_plan (plan.ts checkAmounts); returns the remaining amount.
create function private.plan_remaining(p_principal jsonb, p_down jsonb) returns bigint
language plpgsql
stable
set search_path = ''
as $$
begin
	if not private.is_minor(p_principal) or (p_principal #>> '{}')::numeric = 0 then
		raise exception using message = 'invalid_principal', errcode = 'P0001';
	end if;
	if not private.is_minor(p_down) then
		raise exception using message = 'invalid_down_payment', errcode = 'P0001';
	end if;
	if (p_down #>> '{}')::bigint >= (p_principal #>> '{}')::bigint then
		raise exception using message = 'down_payment_too_large', errcode = 'P0001';
	end if;
	return (p_principal #>> '{}')::bigint - (p_down #>> '{}')::bigint;
end;
$$;

-- Plan ----------------------------------------------------------------------------------------------

-- Input: { principal, down_payment, count, period, first_due_date } → [{ seq, due_date, amount_minor }].
create function private.generate_plan(p_input jsonb) returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
	v_remaining bigint := private.plan_remaining(p_input -> 'principal', p_input -> 'down_payment');
	v_count_json jsonb := p_input -> 'count';
	v_count int;
	v_period text := p_input ->> 'period';
	v_first_text text := p_input ->> 'first_due_date';
	v_first date;
	v_base bigint;
	v_last bigint;
begin
	if not private.is_minor(v_count_json)
		or (v_count_json #>> '{}')::numeric not between 1 and 120 then
		raise exception using message = 'invalid_count', errcode = 'P0001';
	end if;
	v_count := (v_count_json #>> '{}')::int;
	if v_remaining < v_count then
		raise exception using message = 'count_exceeds_remaining', errcode = 'P0001';
	end if;
	if v_first_text is not null then
		v_first := private.try_date(v_first_text);
		if v_first is null then
			raise exception using message = 'invalid_due_date', errcode = 'P0001';
		end if;
	elsif v_count > 1 then
		raise exception using message = 'due_date_required', errcode = 'P0001';
	end if;
	if v_period is null or v_period not in ('monthly', 'weekly', 'biweekly') then
		raise exception using message = 'invalid_period', errcode = 'P0001';
	end if;

	v_base := v_remaining / v_count;
	v_last := v_remaining - v_base * (v_count - 1);
	-- Every date is offset from the first due date, never from the previous row, so month-end clamps
	-- (31 Jan → 28 Feb) do not drift; date + interval 'n months' clamps to the month's last day.
	return (
		select jsonb_agg(
			jsonb_build_object(
				'seq', k + 1,
				'due_date', case
					when v_first is null then null
					when v_period = 'monthly' then to_char((v_first + make_interval(months => k))::date, 'YYYY-MM-DD')
					when v_period = 'weekly' then to_char(v_first + 7 * k, 'YYYY-MM-DD')
					else to_char(v_first + 14 * k, 'YYYY-MM-DD')
				end,
				'amount_minor', case when k = v_count - 1 then v_last else v_base end
			)
			order by k
		)
		from generate_series(0, v_count - 1) as k
	);
end;
$$;

-- Input: { principal, down_payment, installments: [{ due_date, amount_minor }] } → rows with seq.
-- Errors carry the 0-based row index in DETAIL, like the TS result's `index`.
create function private.validate_plan(p_input jsonb) returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
	v_remaining bigint := private.plan_remaining(p_input -> 'principal', p_input -> 'down_payment');
	v_rows jsonb := p_input -> 'installments';
	v_count int;
	v_row jsonb;
	v_index int := 0;
	v_due date;
	v_previous date;
	v_total numeric := 0;
	v_plan jsonb := '[]'::jsonb;
begin
	if jsonb_typeof(v_rows) is distinct from 'array' or jsonb_array_length(v_rows) = 0 then
		raise exception using message = 'empty_plan', errcode = 'P0001';
	end if;
	v_count := jsonb_array_length(v_rows);
	if v_count > 120 then
		raise exception using message = 'invalid_count', errcode = 'P0001';
	end if;

	for v_row in select value from jsonb_array_elements(v_rows) loop
		if not private.is_minor(v_row -> 'amount_minor') or (v_row ->> 'amount_minor')::numeric = 0 then
			raise exception using message = 'non_positive_installment', errcode = 'P0001', detail = v_index::text;
		end if;
		if v_row -> 'due_date' is null or jsonb_typeof(v_row -> 'due_date') = 'null' then
			if v_count > 1 then
				raise exception using message = 'due_date_required', errcode = 'P0001', detail = v_index::text;
			end if;
			v_due := null;
		else
			v_due := private.try_date(v_row ->> 'due_date');
			if v_due is null or jsonb_typeof(v_row -> 'due_date') <> 'string' then
				raise exception using message = 'invalid_due_date', errcode = 'P0001', detail = v_index::text;
			end if;
			if v_previous is not null and v_due < v_previous then
				raise exception using message = 'dates_not_ascending', errcode = 'P0001', detail = v_index::text;
			end if;
			v_previous := v_due;
		end if;
		v_total := v_total + (v_row ->> 'amount_minor')::numeric;
		v_plan := v_plan || jsonb_build_array(jsonb_build_object(
			'seq', v_index + 1,
			'due_date', to_char(v_due, 'YYYY-MM-DD'),
			'amount_minor', (v_row ->> 'amount_minor')::bigint
		));
		v_index := v_index + 1;
	end loop;

	if v_total <> v_remaining then
		raise exception using message = 'sum_mismatch', errcode = 'P0001';
	end if;
	return v_plan;
end;
$$;

-- Allocation ----------------------------------------------------------------------------------------

-- Input: { installments: [{ seq, amount_minor, paid_minor }], amount } → [{ seq, amount_minor }], FIFO by seq.
create function private.allocate_payment(p_input jsonb) returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
	v_amount jsonb := p_input -> 'amount';
	v_left bigint;
	v_owed numeric := 0;
	v_row record;
	v_take bigint;
	v_result jsonb := '[]'::jsonb;
begin
	-- Installments come from our own tables; a broken invariant is a bug, not user input.
	if exists (
		select 1 from jsonb_array_elements(p_input -> 'installments') as i
		where not private.is_minor(i -> 'amount_minor') or (i ->> 'amount_minor')::numeric = 0
			or not private.is_minor(i -> 'paid_minor')
			or (i ->> 'paid_minor')::numeric > (i ->> 'amount_minor')::numeric
	) then
		raise exception 'invalid_installment' using errcode = 'XX000';
	end if;
	if not private.is_minor(v_amount) or (v_amount #>> '{}')::numeric = 0 then
		raise exception using message = 'invalid_amount', errcode = 'P0001';
	end if;
	select coalesce(sum((i ->> 'amount_minor')::numeric - (i ->> 'paid_minor')::numeric), 0) into v_owed
	from jsonb_array_elements(p_input -> 'installments') as i;
	if (v_amount #>> '{}')::numeric > v_owed then
		raise exception using message = 'amount_exceeds_outstanding', errcode = 'P0001';
	end if;

	v_left := (v_amount #>> '{}')::bigint;
	for v_row in
		select (i ->> 'seq')::int as seq, (i ->> 'amount_minor')::bigint - (i ->> 'paid_minor')::bigint as open
		from jsonb_array_elements(p_input -> 'installments') as i
		order by (i ->> 'seq')::int
	loop
		exit when v_left = 0;
		v_take := least(v_left, v_row.open);
		if v_take > 0 then
			v_result := v_result || jsonb_build_array(jsonb_build_object('seq', v_row.seq, 'amount_minor', v_take));
			v_left := v_left - v_take;
		end if;
	end loop;
	return v_result;
end;
$$;

-- Terms hash (ADR-014) ------------------------------------------------------------------------------

-- Keys sorted by code point ("C"), no whitespace, string escaping as JSON.stringify (to_json does the
-- same escapes), integers only. jsonb::text cannot be used: it adds spaces and sorts keys by length.
create function private.canonical_json(p_value jsonb) returns text
language plpgsql
stable
set search_path = ''
as $$
declare
	v_type text := jsonb_typeof(p_value);
	v_number numeric;
begin
	case v_type
		when 'null' then
			return 'null';
		when 'string' then
			return to_json(p_value #>> '{}')::text;
		when 'number' then
			v_number := (p_value #>> '{}')::numeric;
			if v_number <> trunc(v_number) or abs(v_number) > 9007199254740991 then
				raise exception 'canonical JSON allows only safe integers' using errcode = '22023';
			end if;
			return v_number::bigint::text;
		when 'array' then
			return '[' || coalesce(
				(select string_agg(private.canonical_json(e.value), ',' order by e.ordinality)
				from jsonb_array_elements(p_value) with ordinality as e),
				''
			) || ']';
		when 'object' then
			return '{' || coalesce(
				(select string_agg(to_json(e.key)::text || ':' || private.canonical_json(e.value), ',' order by e.key collate "C")
				from jsonb_each(p_value) as e),
				''
			) || '}';
		else
			raise exception 'canonical JSON does not support %', v_type using errcode = '22023';
	end case;
end;
$$;

create function private.terms_hash(p_terms jsonb) returns text
language sql
stable
set search_path = ''
as $$
	select encode(sha256(convert_to(private.canonical_json(p_terms), 'UTF8')), 'hex');
$$;

-- Only security definer RPCs (running as the owner) call these.
revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function private.can_view_agreement(uuid) to authenticated;
